// Moves: The body opens to its own height by Unfold, closing fades first, then folds; the chevron turns on settle and presses 3%. Still: opens and closes at once.
// Phone: Stacks: time and verdict on one line, then the person, then what was asked.
// moves:end
import { useState } from "react";
import { Card, CardColumns, SignInRow } from "ui";

const at = (minutesAgo: number) => {
  const d = new Date(Date.now() - minutesAgo * 60_000);
  return [d.getHours(), d.getMinutes(), d.getSeconds()].map((n) => String(n).padStart(2, "0")).join(":");
};
const person = (name: string) => <span style={{ fontSize: 14.5, fontWeight: 600 }}>{name}</span>;
const body = (
  <div style={{ fontSize: 13.5, color: "var(--muted)", lineHeight: 1.55 }}>
    Syndra read her roles from Zitadel, found Operator on the laser cutter, and left the CNC router out because it is not in this app&apos;s roles.
  </div>
);

const rows = [
  { id: "a", minutes: 2, name: "Roman Reigns", answered: "Operator on Laser cutter", tone: "healthy", word: "Matches" },
  { id: "b", minutes: 9, name: "Damian Priest", answered: "No roles for this app", tone: "warn", word: "Checked" },
  { id: "c", minutes: 31, name: "Jey Uso", answered: "Zitadel did not answer", tone: "danger", word: "Failed" },
] as const;

/** One captured sign-in per verdict; the first is open, the others fold. */
export const Live = () => {
  const [open, setOpen] = useState<string | null>("a");
  return (
    <Card>
      <CardColumns>
        <span style={{ width: 124 }}>Time</span>
        <span style={{ width: 210 }}>Person</span>
        <span style={{ width: 120 }}>Asked for</span>
        <span style={{ flex: 1 }}>Syndra answered</span>
      </CardColumns>
      {rows.map((r) => (
        <SignInRow
          key={r.id}
          time={at(r.minutes)}
          person={person(r.name)}
          asked="Print Queue"
          answered={r.answered}
          verdict={{ tone: r.tone, word: r.word }}
          open={open === r.id}
          onToggle={() => setOpen(open === r.id ? null : r.id)}
        >
          {body}
        </SignInRow>
      ))}
    </Card>
  );
};
